# Look at all relationships for both 4s and 7s
from collections import defaultdict

special_values = {}
for r in range(5):
    for c in range(30):
        val = demo1_input[r][c]
        if val in [1, 2, 6, 8]:
            special_values[(r,c)] = val

all_4s = [(r,c) for r in range(5) for c in range(30) 
          if demo1_input[r][c] == 0 and demo1_output[r][c] == 4]
all_7s = [(r,c) for r in range(5) for c in range(30) 
          if demo1_input[r][c] == 0 and demo1_output[r][c] == 7]

def get_special_at(pos, specials_dict):
    sr, sc = pos
    closest = None
    min_dist = float('inf')
    for sp, sv in specials_dict.items():
        dist = abs(sr-sp[0]) + abs(sc-sp[1])
        if dist < min_dist:
            min_dist = dist
            closest = (sp, sv)
    return closest

# Group by source type
source_4 = defaultdict(list)
source_7 = defaultdict(list)

for p in all_4s:
    spec = get_special_at(p, special_values)
    if spec:
        source_4[spec].append((p[0]-spec[0], p[1]-spec[1]))

for p in all_7s:
    spec = get_special_at(p, special_values)
    if spec:
        source_7[spec].append((p[0]-spec[0], p[1]-spec[1]))

